import { useResource, useField } from 'qortex-resource-react';

function ProfileForm() {
  const { resource, isChanged, isSaving, save, resetDraft } = useResource({
    initialData: { name: '', email: '' },
    validate: {
      on: 'blur',
      fields: {
        name: (v) => (!v ? 'Required' : null),
      },
    },
    source: { save: (d) => api.saveProfile(d) },
  });

  return (
    <form onSubmit={(e) => { e.preventDefault(); save(); }}>
      <NameField resource={resource} />
      <button disabled={!isChanged || isSaving}>Save</button>
      <button type="button" onClick={resetDraft}>Reset</button>
    </form>
  );
}

function NameField({ resource }) {
  const { value, error, onChange, onBlur } = useField(resource, 'name');
  return (
    <>
      <input
        value={value ?? ''}
        onChange={(e) => onChange(e.target.value)}
        onBlur={onBlur}
      />
      {error && <span>{error}</span>}
    </>
  );
}
